// The self-test has NO way in from the interface. It is a code diagnostic:
// not a learner's business, not a reviewer's either, and a hidden gesture is
// still a door. It is turned on from a console instead (`patenteSelfTest()`,
// defined near ttsSelfTest), which is where whoever is debugging already is.
let _selfTestOn = false;
const STORAGE_KEY     = 'patente_progress';
const BACKUP_INTERVAL_DAYS = 7;
const BACKUP_NUDGE_AFTER   = 20; // show nudge after this many answers
const LEVEL_KEY      = 'patente_level';
const DEV_KEY        = 'patente_dev';     // reviewer/developer mode toggle
const FLAGS_KEY      = 'patente_flags';   // locally saved issue reports
const APP_SUBMIT_TOKEN = 'cc625673555839cf5e0d0643f59c0e42'; // must match $TOKEN in submit-flags.php
const REVIEWER_KEY   = 'patente_reviewer';  // optional reviewer code, identifies trusted reviewers
const QUICK_KEY      = 'patente_quick';   // "Quick" mode: show only each card's abridged statement set
const FULL_CARDS_KEY = 'patente_full_cards'; // cards promoted back to full depth (e.g. after a mock miss)
const SETTINGS_TS_KEY   = 'patente_settings_ts';        // last-write-wins stamp for synced scalar settings
const FLAGS_CLEARED_KEY = 'patente_flags_cleared_at';   // tombstone: flags at/before this time are gone
