// ── State ─────────────────────────────────────────────────────────────
let questions    = [];      // loaded from questions.json
let vocabulary   = {};      // loaded from vocabulary.json
let topicReviews = {};      // loaded from topic_reviews.json: { [topic]: { en, it } }
let imageAliases = {};      // loaded from image_aliases.json: { [src]: [twin srcs] } (byte-identical bank images)
let reviewAnchors = {};     // loaded from review_anchors.json: { [cardId]: { en, it } } review section for cards without a figure
let abridgedMap  = {};      // loaded from abridged.json: { [cardId]: [kept statement numbers] }
let reference    = {};      // loaded from reference.json: the Reference page's numbers and lists
let vocabSets    = [];      // loaded from vocab_sets.json: one English word, several Italian ones
let grammarTopics = [];     // loaded from grammar.json: the Reference page's Grammar tab (English-only)
let progress     = {};      // { [id]: { seen, correct, streak, lastSeen } } for currentLevel
let currentLevel = 1;       // 1 = English, 2 = Italian + hints, 3 = Italian only
let session   = {
  queue:       [],       // ordered list of quesito ids for this session
  index:       0,
  mode:        'study',  // 'study' | 'exam'
  examAnswers: [],
};

// ── Localization ──────────────────────────────────────────────────────
// Two languages, two rules. Static elements keep their English text in the DOM
// (the no-JS default) and get an Italian override applied when the interface
// is Italian. Dynamic strings come from the T table via t().
//
// uiLang() is the language of the APP: labels, buttons, settings, dashboard,
// progress messages, dialogs, topic names in navigation. It follows the
// USER, not the level: Italian for a visitor whose browser asks for Italian,
// English for everyone else. An American working at Italiano is still an
// American: decoding the app's own instructions teaches nothing the exam
// tests and costs attention the questions need. (The Settings language
// override, when set, decides it instead.)
//
// contentLang() is the language of the EXAM MATERIAL: the explanations and
// the topic reviews. That one does follow the level, Italian from L2 up,
// because reading the rules in Italian is precisely the skill the hint level
// exists to build (the EN pills remain as a check). The statements themselves
// are always Italian.
function uiLang() {
  try { return browserPrefersItalian() ? 'it' : 'en'; } catch { return 'en'; }
}
function contentLang() { return currentLevel >= 2 ? 'it' : 'en'; }

