  'review.ambigHint': { en: 'Some official questions are worded so that the opposite answer could be argued. Only the official answer is accepted, so memorize each one. Questions you keep missing are in the weak spots on the main page.', it: 'Alcune domande ufficiali sono formulate in modo che si potrebbe sostenere la risposta opposta. Viene accettata solo la risposta ufficiale, quindi memorizzale una per una. Le domande che continui a sbagliare sono nei punti deboli della pagina principale.' },
  'review.ambigEmpty': { en: 'Nothing here yet. Ambiguous questions appear once you meet them while studying.', it: 'Qui non c\u2019\u00e8 ancora nulla. Le domande ambigue compaiono quando le incontri studiando.' },
  'review.noneNumbers': { en: 'No number matches that search.', it: 'Nessun numero corrisponde alla ricerca.' },
