  'settings.examMix':      { en: '📋 Mock-exam question mix', it: '📋 Composizione della simulazione' },
  'settings.examMixDesc':  { en: "How the 30 statements are drawn. The Ministry publishes only that the draw is random, so 'every topic' follows what driving-school course books teach: one statement per topic, plus five more from the topics treated as most safety-relevant.", it: 'Come si estraggono le 30 affermazioni. Il Ministero pubblica solo che l\u2019estrazione \u00e8 casuale, quindi \u00abogni argomento\u00bb segue quanto insegnano i manuali delle autoscuole: un\u2019affermazione per argomento, pi\u00f9 altre cinque dagli argomenti pi\u00f9 rilevanti per la sicurezza.' },
  'settings.examMixTopics':{ en: 'Every topic (25 + 5)', it: 'Ogni argomento (25 + 5)' },
