  'settings.explCorrect':     { en: '💡 Show the explanation after a correct answer', it: '💡 Mostra la spiegazione anche se rispondi bene' },
  'settings.explCorrectDesc': { en: 'Off: after a correct answer the explanation stays closed behind a "Why?" button. After a wrong answer it always opens.', it: 'Spento: dopo una risposta esatta la spiegazione resta chiusa dietro un pulsante «Perché?». Dopo un errore si apre sempre.' },
  'settings.autoScroll':     { en: '↓ Scroll on after answering', it: '↓ Scorri avanti dopo la risposta' },
  'settings.autoScrollDesc': { en: 'After each answer, the page moves so the explanation sits at the top and the next question follows right below it.', it: 'Dopo ogni risposta la pagina si sposta in modo che la spiegazione sia in alto e la domanda successiva subito sotto.' },
  'settings.reviewNote':     { en: '📖 Show the note at the top of the topic notes', it: '📖 Mostra la nota in cima agli appunti' },
  'settings.reviewNoteDesc': { en: 'When you open the notes from a question, a line at the top explains that a duty, ban or permission missing from the notes does not apply.', it: 'Quando apri gli appunti da una domanda, una riga in cima spiega che un obbligo, un divieto o un permesso assente dagli appunti non si applica.' },
  'settings.sound':       { en: '🔔 Answer sound', it: '🔔 Suono di conferma' },
  'settings.soundDesc':   { en: 'A short tone on every answer: two rising notes when you are right, one lower note when you are wrong, and a little flourish when you clear a whole card with nothing missed.', it: 'Un breve suono a ogni risposta: due note ascendenti se è giusta, una nota più bassa se è sbagliata, e un piccolo arpeggio quando completi una scheda senza errori.' },
  'settings.ignoreSilent':     { en: '🔕 Play the answer tone even when the phone is silenced', it: '🔕 Suono della risposta anche con la suoneria disattivata' },
  'settings.ignoreSilentDesc': { en: 'On an iPhone, the side switch silences this app. With this on, the answer tone is heard anyway, at the cost of pausing music or a podcast for the moment the tone plays. The 🔊 spoken text is NOT covered: iOS gives a web page no way to exempt spoken text from that switch, so reading statements aloud needs the ringer on.', it: 'Su iPhone il tasto laterale silenzia questa app. Con questa opzione il suono della risposta si sente comunque, al prezzo di mettere in pausa la musica o un podcast per il tempo del suono. Il testo letto con 🔊 NON è coperto: iOS non dà a una pagina web alcun modo di esentare la voce da quel tasto, quindi per ascoltare le frasi serve la suoneria attiva.' },
  'settings.vibrate':     { en: '📳 Vibration', it: '📳 Vibrazione' },
  'settings.vibrateDesc': { en: 'A short vibration on every answer: one tap when you are right, two when you are wrong. Useful with the ringer off. Not every phone supports it.', it: 'Una breve vibrazione a ogni risposta: un colpo se è giusta, due se è sbagliata. Utile con la suoneria spenta. Non tutti i telefoni la supportano.' },
