function t(key, ...args) { return tl(uiLang(), key, ...args); }
// The mock exam's own screen is drawn in ITALIAN for every browser
// (20261008v, maintainer, 2026-10-02: it must match the look and feel of the
// Ministry's terminal, which SIDA's facsimile reproduces). xt() is t() pinned
// to Italian, used only on the sheet, the Riepilogo and the result line.
function xt(key, ...args) { return tl('it', key, ...args); }
function tl(lang, key, ...args) {
  const e = T[key];
  let s = e ? (e[lang] ?? e.en) : key;
  args.forEach((a, i) => { s = s.split('{' + i + '}').join(a); });
  return s;
}


// Apply the current UI language to all static elements (idempotent).
function applyI18n() {
  const it = uiLang() === 'it';
  document.documentElement.lang = it ? 'it' : 'en';
  // The English title is index.html's own, which is written for search
  // (20261012c): Google renders the page, so a title set here is the one it
  // reads. Only the Italian face replaces it.
  if (applyI18n._title === undefined) applyI18n._title = document.title;
  document.title = it ? 'Patente B — Studio per la patente' : applyI18n._title;
  // The manifest names the app in install prompts and the app switcher. The
  // English one says the app is written for Americans (20261017g,
  // maintainer); an Italian browser gets manifest-it.json. The home-screen
  // label itself stays the short name "Patente B" in both.
  const mf = document.querySelector('link[rel="manifest"]');
  if (mf) { const want = it ? 'manifest-it.json' : 'manifest.json'; if (mf.getAttribute('href') !== want) mf.setAttribute('href', want); }
  document.querySelectorAll('[data-i18n]').forEach(el => {
    if (el._en === undefined) el._en = el.textContent;
    const v = STATIC_IT[el.dataset.i18n];
    el.textContent = it && v != null ? v : el._en;
  });
  document.querySelectorAll('[data-i18n-html]').forEach(el => {
    if (el._enHtml === undefined) el._enHtml = el.innerHTML;
    const v = STATIC_IT[el.dataset.i18nHtml];
    el.innerHTML = it && v != null ? v : el._enHtml;
  });
  document.querySelectorAll('[data-i18n-attr]').forEach(el => {
    const [attr, key] = el.dataset.i18nAttr.split(':');
    el._enAttr = el._enAttr || {};
    if (el._enAttr[attr] === undefined) el._enAttr[attr] = el.getAttribute(attr) || '';
    const v = STATIC_IT[key];
    el.setAttribute(attr, it && v != null ? v : el._enAttr[attr]);
  });
  // Buttons whose text is set in JS (not data-i18n) must be re-synced on switch.
  try { syncThemeToggle(); } catch {}
  try { document.querySelectorAll('.search-clear')
          .forEach(b => b.setAttribute('aria-label', t('search.clear'))); } catch {}
  try { updateResumeButton(); } catch {}
  // The Settings dialog keeps its own language choice — re-apply it, since the
  // pass above just repainted its elements in the UI language.
  try { paintSettingsLang(); } catch {}
  try { paintVocabChrome(); } catch {}
  try { syncSettings(); } catch {}
  try { syncNavHeight(); } catch {}
  try { applyTooltips(); } catch {}
  try { applyRouteTab(); } catch {}
}

// The licensing How-to is two routes in tabs (20261007c, maintainer,
// 2026-10-01): through a driving school, or as a private candidate, each a
// numbered sequence in the order the learner does it. The panel is one
// data-i18n-html block repainted per language, so the chosen tab is applied
// after every paint, and the click is delegated. The choice is remembered on
// the device; the school route is the default, being the common one.
const ROUTE_KEY = 'patente_howto_route';
function howtoRoute() {
  try { return localStorage.getItem(ROUTE_KEY) === 'private' ? 'private' : 'school'; } catch { return 'school'; }
}
function applyRouteTab() {
  const route = howtoRoute();
  document.querySelectorAll('[data-i18n-html="next.body"]').forEach(box => {
    box.querySelectorAll('.route-tab').forEach(b => {
      const on = b.dataset.route === route;
      b.classList.toggle('is-on', on);
      b.setAttribute('aria-selected', on ? 'true' : 'false');
    });
    box.querySelectorAll('.route-pane').forEach(p => p.classList.toggle('hidden', p.dataset.route !== route));
  });
}
document.addEventListener('click', e => {
  const tab = e.target.closest('.route-tab');
  if (!tab) return;
  try { localStorage.setItem(ROUTE_KEY, tab.dataset.route); } catch { }
  applyRouteTab();
});

