  // which one is meant ("incrocio" under "The rules"), so it carries no weight
  // once there are enough blocks to judge that.
  const df = new Map();
  for (const c of cands) for (const w of st) if (c.toks.has(w)) df.set(w, (df.get(w) || 0) + 1);
  const n = cands.length;
