  // two. The gap alone is not enough: it is measured as a share of the
  // statement's words, so a long statement divides every gap down and a block
  // that wins two-to-one can still miss a fixed 0.15. That is what kept 24116
  // (the trailer's swept path, 0.29 against 0.14) on the heading.
  const clear = need => best.frac - second >= need || (second > 0 && best.frac >= 2 * second);
