// Does this topic's review (either language) show the given image?
function reviewHasImage(topic, src) {
  if (!src) return false;
  const entry = topicReviews[topic];
  if (!entry) return false;
  const needle = '(' + src + ')';
  return ['en', 'it'].some(l => (entry[l] || '').includes(needle));
}
// The review figure to open for a study card: its own image when the review
// shows it; otherwise, for a variant card (one statement with its own
// picture, e.g. 4350_22020), the base card's image, or any review figure
// filed under the same quesito number. Null when nothing matches.
function reviewImageFor(topic, q, ownOnly = false) {
  if (!q || !q.image) return null;
  if (reviewHasImage(topic, q.image)) return q.image;
  for (const twin of (imageAliases[q.image] || [])) if (reviewHasImage(topic, twin)) return twin;
  if (ownOnly) return null;
  const base = q.base_id !== undefined ? q.base_id : q.id;
  const baseCard = questions.find(x => x.id === base && !x.variant);
  if (baseCard && baseCard.image && reviewHasImage(topic, baseCard.image)) return baseCard.image;
  const entry = topicReviews[topic];
  if (!entry) return null;
  const re = new RegExp('\\((domandeb_images/' + base + '(?:[._])[^)]*)\\)');
  for (const l of ['en', 'it']) {
    const m = (entry[l] || '').match(re);
    if (m) return m[1];
  }
  // The same drawing under another card's file name (the Ministry reuses one
  // picture across cards): any byte-identical twin the review does show.
  for (const twin of (imageAliases[q.image] || [])) if (reviewHasImage(topic, twin)) return twin;
  if (baseCard && baseCard.image) for (const twin of (imageAliases[baseCard.image] || [])) if (reviewHasImage(topic, twin)) return twin;
  return null;
}

// Open at the figure that matches the study card's image, and flash it so the
