// ── Modal focus management (accessibility) ───────────────────────────
// Dialogs previously opened without moving focus into them and without
// restoring it on close, leaving keyboard and screen-reader users stranded on
// the page behind. These helpers move focus into a dialog on open, restore it to
// the triggering control on close, and trap Tab within the open dialog.
let _modalReturnFocus = null;

function focusableIn(el) {
  return [...el.querySelectorAll(
    'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), ' +
    'textarea:not([disabled]), [tabindex]:not([tabindex="-1"])'
  )].filter(n => !n.hasAttribute('hidden') && n.offsetParent !== null);
}

// Call right after un-hiding a dialog overlay.
function focusModal(overlay) {
  _modalReturnFocus = document.activeElement;
  const dialog = overlay.querySelector('[role="dialog"]') || overlay;
  const first = focusableIn(dialog)[0];
  (first || dialog).focus();
}

// Call after re-hiding the overlay to restore focus to the trigger.
function restoreModalFocus() {
  const el = _modalReturnFocus;
  _modalReturnFocus = null;
  if (el && typeof el.focus === 'function' && document.contains(el)) el.focus();
}

// Trap Tab / Shift-Tab inside whichever dialog overlay is currently open.
document.addEventListener('keydown', e => {
  if (e.key !== 'Tab') return;
  const overlay = [...document.querySelectorAll('.review-overlay')]
    .find(o => !o.classList.contains('hidden'));
  if (!overlay) return;
  const dialog = overlay.querySelector('[role="dialog"]') || overlay;
  const f = focusableIn(dialog);
  if (!f.length) return;
  const first = f[0], last = f[f.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
});
// Size each review figure by its CONTENT, not its outer height. Equal-height makes
// a one-word town sign (TARANTO) and an eight-line exit sign the same height, so
// one has huge letters and the other tiny ones. We instead blend equal-height with
// equal-area: h = H0 * (1/aspect)^BETA. BETA=0 is pure equal-height; BETA=0.5 is
// pure equal-area (which balances text size but shrinks wide plates); ~0.4 keeps
// same-density rows (e.g. road-number plates) tidy while fixing the mixed-density
