  dense:  { H0: 88,  hmin: 58, hmax: 108, wmax: 140 },
  big:    { H0: 210, hmin: 140, hmax: 300, wmax: 430 },  // "!big" hint: detailed sign
  small:  { H0: 90,  hmin: 52, hmax: 105, wmax: 210 },   // "!small" hint: sparse sign
