window.addEventListener('resize', () => {
  const ov = document.getElementById('review-overlay');
  if (!ov || ov.classList.contains('hidden')) return;
  ov.querySelectorAll('.review-fig-img').forEach(im => { if (im.complete && im.naturalWidth) sizeReviewFig(im); });
});
function sizeReviewFig(img) {
  if (!img.naturalWidth || !img.naturalHeight) return;
  const r = img.naturalWidth / img.naturalHeight;   // content is tightly cropped
  const figs = img.closest('.review-figs');
  const rowKind = !figs ? 'few'
             : figs.classList.contains('review-figs-single') ? 'single'
             : figs.classList.contains('review-figs-pair') ? 'pair'
             : figs.classList.contains('review-figs-few') ? 'few' : 'dense';
  // A per-image "!big"/"!small" hint overrides the row's default size.
  const fig0 = img.closest('.review-fig');
  const kind = fig0 && fig0.classList.contains('fig-xl') ? 'xl'
             : fig0 && fig0.classList.contains('fig-lg') ? 'big'
             : fig0 && fig0.classList.contains('fig-sm') ? 'small'
             : rowKind;
  const c = REVIEW_FIG_CFG[kind];
  let h = c.H0 * Math.pow(1 / r, REVIEW_FIG_BETA);
  h = Math.max(c.hmin, Math.min(c.hmax, h));
  let w = h * r;
  if (w > c.wmax) { w = c.wmax; h = w / r; }
  // Never wider than the row it sits in (a wide plate on a phone): the row is
  // block-level, so its width is known; 12px is the image's padding + border.
  const avail = figs ? figs.clientWidth - 12 : 0;
  if (avail > 60 && w > avail) { w = avail; h = w / r; }
  img.style.width = Math.round(w) + 'px';
  img.style.height = Math.round(h) + 'px';
  // Constrain the caption to the figure's width so it wraps beneath the image
  // instead of stretching wider than it (which left the image floating in dead
  // space). offsetWidth includes the image's padding + border = the visible box.
  // Dense rows are a fixed-width CSS grid, so the caption already wraps within the
  // cell — leave it to CSS. For the flexible 2-3 image rows, cap the caption to the
  // figure's own box width (with a small readable floor) so it wraps beneath the
  // image instead of stretching wider than it and leaving the image in dead space.
  if (rowKind !== 'dense') {
    const cap = fig0 && fig0.querySelector('figcaption');
    if (cap) cap.style.maxWidth = Math.max(img.offsetWidth, 120) + 'px';
  }
}
document.addEventListener('load', e => {
  const img = e.target;
  if (img instanceof HTMLImageElement && img.classList.contains('review-fig-img')) {
    sizeReviewFig(img);
  }
}, true);

// Write to localStorage, returning true on success. A failed write (most often
// the storage quota being exhausted, or a Safari private-mode block) would
// otherwise throw and silently lose the user's progress — the one thing this app
// must never do. On failure we log it and warn the user once, so they can export
// a backup before anything is lost.
let _storageWarned = false;
function safeSetItem(key, value) {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch (err) {
    console.error('localStorage write failed for', key, err);
    showStorageWarning();
    return false;
  }
}

function showStorageWarning() {
  if (_storageWarned || document.getElementById('storage-banner')) return;
  _storageWarned = true;
  const bar = document.createElement('div');
  bar.id = 'storage-banner';
  bar.className = 'update-banner storage-banner';
  bar.setAttribute('role', 'alert');
  bar.innerHTML =
    `<span class="update-text">${t('storage.full')}</span>` +
    `<button id="storage-dismiss" class="banner-dismiss" aria-label="${t('install.dismissA')}">✕</button>`;
  document.body.appendChild(bar);
  document.getElementById('storage-dismiss').addEventListener('click', () => bar.remove());
}

function storageKeyForLevel(lvl) {
  return STORAGE_KEY + '_L' + lvl;
}

// One live object per level. Every read and write of a level's progress goes
// through these two functions, so the cache cannot go stale, and callers that
// used to get a fresh parse now get the live object, which is more current,
// not less. Before this the dashboard parsed all three ~0.5 MB blobs on every
// render, and the level ladder below would have added two more parses per
// correct answer.
const _progressCache = new Map();
function loadProgressForLevel(lvl) {
  if (_progressCache.has(lvl)) return _progressCache.get(lvl);
  let prog;
  try { prog = JSON.parse(localStorage.getItem(storageKeyForLevel(lvl)) || '{}'); }
  catch (err) { console.error('localStorage read failed for level', lvl, err); prog = {}; }
  _progressCache.set(lvl, prog);
  return prog;
}

function saveProgressForLevel(lvl, prog) {
  _progressCache.set(lvl, prog);
  safeSetItem(storageKeyForLevel(lvl), JSON.stringify(prog));
}

// ── Level ladder: credit flows downward ───────────────────────────────
// The three levels are one ladder, not three parallel tracks. Italiano (L3) is
// the only level the real exam tests; English (L1) and Italian (L2) exist to
// get a learner there. So a statement answered correctly at a higher level is
// credited to every level below it: nobody should have to prove in English
// what they have already proven under exam conditions. Without this, clearing
// the bank meant clearing it three times, about 21,000 answers.
//
// Credit only ever flows DOWN and only ever ADDS. A miss at L3 does not touch
// L1, and a lift never lowers a field. The lift is a per-field max, the same
// rule the sync merge uses, so it is idempotent and commutes with sync: lifted
// records merge cleanly with whatever another device holds.
//
// It runs three ways, all through the same function: incrementally on each
// correct answer, retroactively at boot (so existing progress is credited on
// upgrade), and after every sync merge (an incoming device may carry higher-
// level mastery the lower levels here have not seen).
function liftStatement(lowerCard, num, higher, official) {
  if (!isStmtMastered(higher)) return false;
  // `lft` marks a record that exists ONLY because credit flowed down: the
  // learner never answered this statement at this level. It matters because
  // the lift raises `seen` to keep correct <= seen, so without the mark such a
  // record is indistinguishable from "answered here and got it right" — which
  // is what made the Final Stretch diagnosis tell an Italian-browser learner
  // that their Italian needed work, on the strength of English answers they
  // had never given (found 2026-09-19). Cleared by a real answer.
  const fresh = !lowerCard.st[num];
  const lower = lowerCard.st[num] || (lowerCard.st[num] = { seen: 0, correct: 0, streak: 0 });
  if (fresh) lower.lft = 1;
  const wasMastered = isStmtMastered(lower);
  const next = {
    correct: Math.max(lower.correct || 0, higher.correct || 0),
    streak:  Math.max(lower.streak  || 0, higher.streak  || 0),
  };
  // A record cannot have been right more often than it was seen.
  next.seen = Math.max(lower.seen || 0, next.correct);
  const streakUp = next.streak !== (lower.streak || 0);
  const changed = next.seen !== (lower.seen || 0) || next.correct !== (lower.correct || 0) || streakUp;
  if (!changed) return 0;
  // Freeze the lower level's miss history BEFORE the lift overwrites the
  // arithmetic it used to be read from (see missCount).
  if (lower.miss === undefined) {
    const had = Math.max(0, (lower.seen || 0) - (lower.correct || 0));
    if (had) lower.miss = had;
  }
  Object.assign(lower, next);
  // Stamped only when the run really moved, so the lift stays idempotent: once
  // the lower level matches, `changed` is false and nothing is written.
  if (streakUp) lower.sAt = Date.now();
  // A newly credited statement displays as answered correctly; one the learner
  // had already answered here keeps the answer they actually gave.
  if (!wasMastered) setGiven(lower, official);
  return wasMastered ? 1 : 2;      // 2 = became cleared just now
}

// Returns the levels at which the statement became cleared by this lift, so
// the daily log can count them toward those levels' pace.
function liftCredit(cardId, num, fromLevel, official) {
  const higher = loadProgressForLevel(fromLevel)[cardId]?.st?.[num];
  const newly = [];
  if (!higher) return newly;
  for (let lvl = fromLevel - 1; lvl >= 1; lvl--) {
    const prog = loadProgressForLevel(lvl);
    const card = prog[cardId] || (prog[cardId] = { lastSeen: null, st: {} });
    if (!card.st) card.st = {};
    const r = liftStatement(card, num, higher, official);
    if (r) {
      card.lastSeen = new Date().toISOString();
      saveProgressForLevel(lvl, prog);
      markSyncDirty();
      if (r === 2) newly.push(lvl);
    }
  }
  return newly;
}

// ── Daily loop: log, streak, rate ─────────────────────────────────────
// The bank is finite but large, and a learner who cannot see the end of it
// gives up before reaching it. This block makes the end visible. A tiny
// per-day log (answered, correct, best run, statements newly cleared at each
// level) feeds three things on the dashboard: today's count, a strip of the
// last 14 days, and the date the learner would be ready at the rate they are
// actually working. None of it exists anywhere else: progress records only
// keep the LATEST time a card was seen, so history has to be accumulated as
// it happens.
//
// There is deliberately no goal and no exam date. Both were here, and both
// turned a description into a verdict: a quiet day failed a quota, and the
// automatic goal rose the moment the learner fell behind, so the app pushed
// hardest exactly when someone was already struggling. What replaced them
// describes and predicts, and nothing more. A quiet day moves the estimated
// date by a little, which is the truth, and carries no judgment.
