  for (const lvl of masteredLevels) dailyBump(d, 'm' + lvl, 1);
  // A correct answer in the weak-spot drill is progress too: it moves the
  // statement toward release from the list. Its statement is usually cleared
  // already, so it clears no level and the day read 0 while the learner
  // drilled (maintainer, 2026-09-30). `w` counts those answers, once each.
