  // WRONG is followed by its explanation, and often by a trip to the Concepts
  // notes, so the interval that runs from it to the next answer is mostly
  // study time. Two conditions therefore: this answer is correct, and the
  // answer that started the interval was not wrong.
  if (ms != null && wasCorrect && !_prevAnswerWrong && !_studiedThisInterval) {
    _sess.ms += ms; _sess.timed++; dailyRecordTime(ms);
  }
  _prevAnswerWrong = !wasCorrect;
  _studiedThisInterval = false;
  _sess.a++;
  if (wasCorrect) { _sess.c++; _sess.run++; if (_sess.run > _sess.bestRun) _sess.bestRun = _sess.run; }
