//   started = at least one ACTIVE statement answered;
//   cleared = the card's ACTIVE (abridged) set is mastered — the same test the
//   study deck uses to retire a card. Using the active set here keeps these
//   counts consistent with the "Card X of N" deck counter (remaining = total
//   - cleared). (cardCleared reads the live `progress`, which is what we pass.)
function countCards(prog) {
  let total = 0, started = 0, cleared = 0;
  let qTotal = 0, qStarted = 0, qCleared = 0;   // individual questions (active set)
  for (const q of questions) {
    total++;
    const act = activeStatements(q.id);
    qTotal += act.length;
    let any = false;
    for (const s of act) {
      const rec = prog[q.id]?.st?.[s.number];
      if (rec && rec.seen > 0) { qStarted++; any = true; }
      if (isStmtMastered(rec)) qCleared++;
    }
    if (any) started++;
    if (cardCleared(q.id)) cleared++;
  }
  return { total, started, cleared, qTotal, qStarted, qCleared };
}

// All three levels are freely selectable — there is no unlock gating. A learner
// can take one topic through L1 → L2 → L3, and a native speaker can start at L3.
// Mid-study or mid-exam: a level swap here would leave the session's queue
// describing the old level's progress, and a mock is Italiano by definition.
function midActivity() {
  try {
    if (document.getElementById('screen-study')?.classList.contains('active')) return true;
    if (session && session.mode === 'exam') return true;
    if (typeof examState !== 'undefined' && examState && examState.timerHandle) return true;
  } catch { }
  return false;
}

function setLevel(lvl) {
  currentLevel = lvl;
  forgetUndoSnapshots();   // a snapshot belongs to the level it was taken at
  localStorage.setItem(LEVEL_KEY, String(lvl));
  stampSettings();   // the level is a synced preference; without this it cannot travel
  progress = loadProgressForLevel(lvl);
  invalidateDrillMemo();
  applyI18n();   // the level changed, but the UI language follows the user
}

// ── Navigation ────────────────────────────────────────────────────────
function bindNav() {
  document.querySelectorAll('.nav-btn[data-screen]').forEach(btn => {
    btn.addEventListener('click', () => {
      endDrillLevel();          // leaving a drill by any route restores the level
      document.querySelectorAll('.nav-btn').forEach(b => b.classList.remove('active'));
      btn.classList.add('active');
      showScreen('screen-' + btn.dataset.screen, false);
      if (btn.dataset.screen === 'dashboard') renderDashboard();
      if (btn.dataset.screen === 'topics')    renderTopicList();
      if (btn.dataset.screen === 'exam')      { clearExamResultPanel(); updateExamAvailability(); }
    });
  });

  document.getElementById('btn-back').addEventListener('click', () => {
    endDrillLevel();
    showScreen('dashboard');
    renderDashboard();
    setNavActive('dashboard');
  });

  // The icon is "home": the dashboard, at the top, with the two long
  // fold-out notes (how to use the app, how the license process works)
  // closed again, so a learner who opened them to read is back to the
  // compact dashboard rather than scrolled into the middle of a page of text.
  //
  // Home PARKS an unfinished drill, which the other exits do not. Tapping a
  // nav tab mid-drill is looking something up and coming back, so ▶ Resume
  // still returns to the weak spots; tapping the icon is going back to the
  // start, so while a topic still has work Resume goes there instead. The
  // round itself stays open, so the drill picks up where it stopped whenever
  // it is started again. Until 20261005g Home CLOSED the round, and a learner
  // with every level cleared, for whom the drill is the only work left, began
  // it again from the first card after every trip home (maintainer,
  // 2026-09-29).
  document.getElementById('nav-logo').addEventListener('click', () => {
    // During a mock the icon is the one way out, and it ends the exam.
    if (document.body.classList.contains('exam-locked')) {
      if (examState.timerHandle && !confirm(t('mock.abandon'))) return;
      abandonExam();
      return;
    }
    _drillParked = true;
    endDrillLevel();
    showScreen('dashboard');
    renderDashboard();
    setNavActive('dashboard');
    document.querySelectorAll('#screen-dashboard details.rules-note[open]')
      .forEach(d => { d.open = false; });
    window.scrollTo(0, 0);
    checkForUpdateQuietly();
  });

  document.getElementById('install-dismiss')?.addEventListener('click', () => {
    localStorage.setItem('patente_install_dismissed', '1');
    document.getElementById('install-banner').classList.add('hidden');
  });

}

function setNavActive(name) {
  document.querySelectorAll('.nav-btn').forEach(b => {
    b.classList.toggle('active', b.dataset.screen === name);
  });
}

function showScreen(name, updateNav = true) {
  // Leaving the study screen ends any drill: drop the missed-statement filter
  // so dashboard stats and later sessions see full cards again.
  const onStudy = (name === 'study' || name === 'screen-study');
  if (!onStudy) _drillStmts = null;
  // Hold the audio device open while studying so answer sounds are immediate;
  // release it when the learner leaves (defined further down, so guard the call
  // for the very first screen shown at boot).
  try { onStudy ? warmAudio() : coolAudio(); } catch { }
  document.querySelectorAll('.screen').forEach(s => {
    s.classList.remove('active');
    s.classList.add('hidden');
  });
  // name can be 'dashboard' or 'screen-dashboard'
  const id = name.startsWith('screen-') ? name : 'screen-' + name;
  const el = document.getElementById(id);
  if (el) { el.classList.remove('hidden'); el.classList.add('active'); }
  if (id === 'screen-vocab') {
    try {
      // Arrive at the TOP, with no search running. The screens are siblings in
      // one scrolling document, so a page opened from halfway down a long
      // study card kept that scroll position and the Reference page opened at
      // whatever happened to be at that height, which on this page is the
      // middle of a word list. The search is cleared for the same reason: the
      // page a learner asked for is the page, not yesterday's query.
      // ...unless the learner has just selected a word in a statement, which
      // is the query they were about to type. See takeStatementSelection.
      refQuery = takeStatementSelection();
      _refScoped = false;
      _refParked = '';
      setReviewSearchBox(refQuery);
      paintVocabChrome();
      renderReviewScreen();
      window.scrollTo(0, 0);
    } catch {}
  }
  // The floating study pills must not outlive the study screen when the
  // learner leaves it while scrolled down (no scroll event fires then).
  try { updateFloatUnans(); } catch {}
  // The nav's progress border belongs to the study session, so it empties on
  // the way out and refills on the way back in.
  try { syncNavProgress(); } catch {}
  // The ▶ button is in the nav on every screen, so it is brought up to date on
  // every screen change, not only when the dashboard draws (20261005j).
  try { updateResumeButton(); } catch {}
  try { updateFloatDrill(); } catch {}
}

// ── Dashboard ─────────────────────────────────────────────────────────
// Compute mock-exam readiness from stored history (last 5 attempts, any level)
const READY_THRESHOLD   = 0.93;   // 93% average = exam-ready
const READY_MIN_MOCKS   = 3;      // need at least this many to declare ready
const READY_WINDOW      = 15;     // superseded in 20261009a by mockRecentSheets' own rule; kept for callers that name a count

// mockReadiness, the plain average of the last mocks against a 93% bar,
// was removed in 20261007i: the chance of passing replaced it everywhere.

// The "ready for the exam" banner (20261007e, maintainer, 2026-10-01). It
// showed at three mocks averaging 93%, said "your last 5" whatever the count,
// and ignored open weak spots. Now it needs the same Student-t prediction as
// the Statistics page, over the last READY_BANNER_MOCKS sheets, at or above
// READY_BANNER_CHANCE, and no weak spot outstanding. Fifteen was the
// maintainer's choice: below about ten sheets the standard deviation is too
// poorly known (its 95% interval at ten runs to 1.8 times the measured one,
// at fifteen to 1.6), and the t already prices a short run, so a learner
// averaging about 1.25 wrong reaches 95% at fifteen while one averaging 2
// never does.
// The figure SHOWN is the chance of FAILING the next sheet (20261007o,
// maintainer, 2026-10-01: more meaningful to a learner deciding whether to
// book), rounded up so it never reads better than the prediction.
function failPct(chance) { return Math.max(0, Math.ceil((1 - chance) * 100 - 1e-9)); }
// The figure as SHOWN (20261009u, maintainer): two significant figures below
// 10% (8.7, 0.43), whole numbers from 10 up, still rounded UP so it never
// reads better than the prediction, with the reader's decimal separator.
function failPctText(chance) {
  const v = Math.max(0, (1 - chance) * 100);
  if (v < 1e-9) return '0';
  const dp = v < 1 ? 2 : v < 10 ? 1 : 0;
  const f = 10 ** dp;
  const up = Math.ceil(v * f - 1e-9) / f;
  const d = up >= 10 ? 0 : dp;
  return up.toLocaleString(uiLang() === 'it' ? 'it-IT' : 'en-US', { minimumFractionDigits: d, maximumFractionDigits: d });
}
// A statement may carry `reading`: the Italian sentence taken apart the way
// the Grammar tab does it (20261007y, maintainer, 2026-10-02, flag 31036),
// drawn after the ENGLISH explanation for a non-Italian browser wherever that
// explanation shows. {rows: [{lab, it, en, main?}], note}; the rows' Italian
// joins to the statement, which validate_data.py checks. `*word*` in the note
// is drawn in italics.
function readingHtml(stmt) {
  const r = stmt && stmt.reading;
  if (!r || !Array.isArray(r.rows) || uiLang() === 'it') return '';
  const ital = x => escHtml(x).replace(/\*([^*]+)\*/g, '<i>$1</i>');
  return `<div class="stmt-reading"><p class="stmt-reading-head">${escHtml(t('reading.head'))}</p><div class="gr-parse">` +
    r.rows.map(x => `<div class="gr-parse-row${x.main ? ' gr-parse-main' : ''}"><span class="gr-parse-lab">${escHtml(x.lab)}</span>` +
      `<span><span class="gr-exit" lang="it">${escHtml(x.it)}</span><i class="gr-parse-en">${escHtml(x.en)}</i></span></div>`).join('') +
    `</div>${r.note ? `<p class="stmt-reading-note">${ital(r.note)}</p>` : ''}</div>`;
}
const READY_BANNER_MOCKS  = 15;
const READY_BANNER_CHANCE = 0.95;
function examReady() {
  const form = mockRecentForm(null, READY_BANNER_MOCKS);
  let weak = 0;
  try { if (italianoComplete()) weak = difficultCards().reduce((a, d) => a + d.stmts.length, 0); } catch { }
  return { ready: !!form && form.chance >= READY_BANNER_CHANCE && weak === 0,
           chance: form ? form.chance : null, n: form ? form.n : 0,
           taken: mockAllSheets().length, weak };
}

// ── Recent form: the chance of passing the NEXT sitting ──────────────────
//
// The question is a PREDICTION about one future sheet, so the right object is
// a prediction interval, not a confidence interval on the average, and the
// right distribution is Student's t on n−1 degrees of freedom. That was the
// maintainer's call on 2026-09-21 and it replaced a plain binomial estimate
// that had two faults.
//
// The binomial pooled every statement in the window and asked what a learner
// with that one success rate would score. It therefore assumed p is CONSTANT
// across sheets, which threw away exactly the thing the maintainer had asked
// about: a learner whose sheets scatter is not the same as one whose sheets
// cluster, even when the two average the same. The binomial cannot tell them
// apart, and gave 78% to both of these windows:
//     1, 2, 6, 1, 2 wrong   (one bad sheet)  -> t-prediction 67%
//     0, 5, 1, 6, 0 wrong   (erratic)        -> t-prediction 63%
// It was also blind to the size of the window: three sheets and thirty
// produced equally confident answers, where the t widens honestly on few.
//
// So: mean and spread of the sheets themselves, then
//     t = (3.5 − mean) / (s · sqrt(1 + 1/n)),  chance = P(T_{n−1} ≤ t)
// The `1 +` is the new sheet's own variation, the `1/n` the uncertainty in the
// mean, which is the whole difference between predicting an observation and
// estimating an average. The 3.5 is a continuity correction: scores are whole
// numbers and the pass mark is "3 or fewer", so the boundary of the continuous
// approximation sits half a step above 3.
//
// THE SPREAD HAS A FLOOR, and it is the binomial one. A sheet draws 30
// statements from a bank of thousands, so even a learner with a perfectly
// steady p scores with SD sqrt(30·p·(1−p)), which is 1.4 wrong at 93%. Five
// sheets can easily land closer together than that by luck (five identical
// scores give s = 0 and would otherwise predict with false certainty), so the
// spread used is `max(observed, binomial)`. The observed value takes over as
// soon as the learner is genuinely more erratic than the sheet's own sampling
// noise, which is the case the maintainer was right about.
//
// The window was 5 sheets until 20261007l, on the argument that the learner
// improves and old sheets understate today. The maintainer overruled it on
// 2026-10-01: fifteen sheets are needed to know the spread (the banner's own
// rule), so discarding sheets below fifteen throws away exactly the evidence
// the estimate lacks. Every mock now counts, up to the latest fifteen, and
// the ring, its note, the pace line and the banner all read the same sheets.

// Independent implementations of log-gamma, the regularized incomplete beta
// and the regularized lower incomplete gamma, written from the published
// formulas (Lanczos approximation with the g = 7, n = 9 coefficients tabulated
// in the open literature; the continued fractions of DLMF 8.17.22 and 8.9.2,
// each evaluated by forward recurrence of its convergents with rescaling).
function logGamma(x) {
  // Reflection keeps the approximation on x >= 0.5.
  if (x < 0.5) return Math.log(Math.PI / Math.abs(Math.sin(Math.PI * x))) - logGamma(1 - x);
  const C = [0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
             -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
             1.5056327351493116e-7];
  const z = x - 1;
  let s = C[0];
  for (let i = 1; i < C.length; i++) s += C[i] / (z + i);
  const t = z + 7.5;
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(s);
}
// The continued fraction of DLMF 8.17.22 for I_x(a, b) / (x^a (1-x)^b / (a B(a,b))):
//   1 / (1 + d1 / (1 + d2 / (1 + ...))), with
//   d_{2m}   = m (b - m) x / ((a + 2m - 1)(a + 2m)),
//   d_{2m+1} = -(a + m)(a + b + m) x / ((a + 2m)(a + 2m + 1)).
// Evaluated through the convergents A_n / B_n, rescaled when they grow.
function betaContinuedFraction(a, b, x) {
  let Aprev = 1, Bprev = 0, A = 1, B = 1;   // A_{-1}/B_{-1} = 1/0, A_0/B_0 = 1/1
  for (let n = 1; n <= 400; n++) {
    const m = Math.floor(n / 2);
    const d = (n % 2 === 0)
      ? m * (b - m) * x / ((a + 2 * m - 1) * (a + 2 * m))
      : -(a + m) * (a + b + m) * x / ((a + 2 * m) * (a + 2 * m + 1));
    const An = A + d * Aprev, Bn = B + d * Bprev;
    Aprev = A; Bprev = B; A = An; B = Bn;
    const scale = Math.abs(B);
    if (scale > 1e100 || (scale > 0 && scale < 1e-100)) { A /= scale; B /= scale; Aprev /= scale; Bprev /= scale; }
    if (n > 2 && Math.abs(A * Bprev - Aprev * B) <= 1e-16 * Math.abs(B * Bprev)) break;
  }
  return B / A;   // the fraction is 1 / (1 + d1 / (1 + ...)), the reciprocal of the convergent
}
function betaInc(a, b, x) {
  if (!(x > 0)) return 0;
  if (x >= 1) return 1;
  const front = Math.exp(a * Math.log(x) + b * Math.log(1 - x) + logGamma(a + b) - logGamma(a) - logGamma(b));
  // The fraction converges fastest for x below the mean of the distribution;
  // past it, the symmetry I_x(a, b) = 1 - I_{1-x}(b, a) is used.
  if (x > (a + 1) / (a + b + 2)) return 1 - betaInc(b, a, 1 - x);
  return front * betaContinuedFraction(a, b, x) / a;
}
// P(a, x): the series 8.7.1 below a + 1, and above it the Legendre continued
// fraction 8.9.2 for Q(a, x), again by forward recurrence of its convergents.
function gammaP(a, x) {
  if (!(x > 0)) return 0;
  const lg = logGamma(a), front = Math.exp(a * Math.log(x) - x - lg);
  if (x < a + 1) {
    let term = 1 / a, sum = term;
    for (let k = 1; k < 1000; k++) { term *= x / (a + k); sum += term; if (Math.abs(term) < 1e-16 * Math.abs(sum)) break; }
    return Math.min(1, front * sum);
  }
  // Q(a,x) = front * 1 / (x + (1-a) / (1 + 1 / (x + (2-a) / (1 + 2 / (x + ...)))))
  let Aprev = 1, Bprev = 0, A = 0, B = 1;   // leading term 0 + 1/(x + ...)
  // partial numerators and denominators: b0 = 0, a1 = 1, b1 = x, then
  // a_{2k} = k - a, b_{2k} = 1; a_{2k+1} = k, b_{2k+1} = x
  for (let n = 1; n <= 1000; n++) {
    const k = Math.floor(n / 2);
    const an = n === 1 ? 1 : (n % 2 === 0 ? k - a : k);
    const bn = n % 2 === 1 ? x : 1;
    const An = bn * A + an * Aprev, Bn = bn * B + an * Bprev;
    Aprev = A; Bprev = B; A = An; B = Bn;
    const scale = Math.abs(B);
    if (scale > 1e100 || (scale > 0 && scale < 1e-100)) { A /= scale; B /= scale; Aprev /= scale; Bprev /= scale; }
    if (n > 2 && Math.abs(A * Bprev - Aprev * B) <= 1e-16 * Math.abs(B * Bprev)) break;
  }
  return Math.max(0, 1 - front * (A / B));
}
// With gammaP, the chi-square quantile by bisection, which the range of a
// standard deviation needs (20261008l).
function chiSquareQuantile(p, df) {
  let lo = 0, hi = Math.max(10, df * 10);
  while (gammaP(df / 2, hi / 2) < p) hi *= 2;
  for (let i = 0; i < 80; i++) { const mid = (lo + hi) / 2; if (gammaP(df / 2, mid / 2) < p) lo = mid; else hi = mid; }
  return (lo + hi) / 2;
}
// The range a standard deviation measured on n values lies in with the given
// probability, from the chi-square distribution of (n − 1)·s²/σ². It is not
// symmetric: the measured value sits nearer the bottom of it.
const SD_RANGE_P = 0.68;
function sdRange(s, n, prob = SD_RANGE_P) {
  if (!(n > 1) || !(s >= 0)) return null;
  const df = n - 1, a = (1 - prob) / 2;
  return { lo: s * Math.sqrt(df / chiSquareQuantile(1 - a, df)), hi: s * Math.sqrt(df / chiSquareQuantile(a, df)) };
}
// The range an average of n values lies in with the given probability:
// mean ± t·s/√n, Student's t on n − 1 degrees of freedom (20261008m).
function tQuantile(p, df) {
  let lo = 0, hi = 50;
  while (studentT(hi, df) < p) hi *= 2;
  for (let i = 0; i < 80; i++) { const mid = (lo + hi) / 2; if (studentT(mid, df) < p) lo = mid; else hi = mid; }
  return (lo + hi) / 2;
}
// Where the NEXT single value should fall: mean ± t·s·√(1 + 1/n), the
// prediction interval. At 90% two-sided its edge is the banner's own test:
// the chance of passing is 95% exactly when the edge clears the pass line
// (20261008n, maintainer: a learner who is not ready should see a range
// that reaches below the pass mark, which the range of the AVERAGE never
// showed).
const NEXT_RANGE_P = 0.90;
function nextRange(mean, s, n, prob = NEXT_RANGE_P) {
  if (!(n > 2)) return null;
  const se = s * Math.sqrt(1 + 1 / n);
  const h = tQuantile(1 - (1 - prob) / 2, n - 1) * se;
  return { lo: mean - h, hi: mean + h, mean, se, df: n - 1 };
}
// P(T ≤ t) for Student's t on `df` degrees of freedom. Agrees with mpmath
// and scipy to twelve decimal places (scripts/check_special_functions.js).
function studentT(t, df) {
  if (typeof t !== 'number' || !(df > 0)) return null;
  if (!isFinite(t)) return t > 0 ? 1 : 0;
  const tail = 0.5 * betaInc(df / 2, 0.5, df / (df + t * t));
  return t > 0 ? 1 - tail : tail;
}

// A sheet cut short by the timer stored only the statements ANSWERED, so its
// `wrong` misses the ones never reached. At the real exam those count against
// you, so they count here: the larger of the two readings is the honest one.
// (The ring above still averages correct/total, which is the older measure;
// this is the one place that is strict about it.)
function sheetWrong(r) {
  const stored = (r.wrong != null) ? r.wrong : (r.total || 0) - (r.correct || 0);
  return Math.max(stored, EXAM_QUESTION_COUNT - (r.correct || 0));
}

// The sheets this measure is allowed to read, newest first: a mock exam with
// something answered on it, at the level the mock runs at.
//
// WHICH sheets (20261009a, maintainer, 2026-10-02: no fixed cap of fifteen).
// Every mock on record counts, since more sheets give a steadier and truer
// figure, EXCEPT when the scores have clearly changed level: then the mocks
// from before the change describe a different learner and are left out.
// "Clearly" is a test, not a judgment. For each way of splitting the history
// into an older part (at least WINDOW_MIN_OLD sheets) and a recent part (at
// least WINDOW_MIN_RECENT, the banner's fifteen), the errors in the recent
// part are compared with what an unchanged error rate would give: under no
// change they are Binomial(all errors, recent share of the sheets). The split
// with the smallest two-sided p is taken when that p is under WINDOW_ALPHA.
// Measured by simulation at 0.02: a steady learner loses old sheets wrongly
// in 4% of histories at 30 mocks and 9% at 50; a learner who improved from
// 2.5 to 1.2 wrong reads 4.5% at mock 40 (true 3.1%), against 8.6% with
// every mock and 4.1% with the last fifteen, and a steady learner reads
// 5.9% +- 2.4 at 60 mocks (true 6.1%) against 8.0% +- 5.0 with the last
// fifteen. An explicit windowN still takes the latest N, for callers that
// want a fixed count.
const WINDOW_ALPHA = 0.02, WINDOW_MIN_RECENT = 15, WINDOW_MIN_OLD = 5;
function binomCdf(k, n, q) {
  if (k < 0) return 0;
  if (k >= n) return 1;
  return betaInc(n - k, k + 1, 1 - q);
}
// Index, in a list of wrong-counts OLDEST FIRST, where the window starts.
function mockWindowStart(wrongs) {
  const n = wrongs.length;
  if (n < WINDOW_MIN_RECENT + WINDOW_MIN_OLD) return 0;
  const total = wrongs.reduce((a, w) => a + w, 0);
  if (!total) return 0;
  let best = 1, at = 0, before = 0;
  for (let c = 1; c <= n - WINDOW_MIN_RECENT; c++) {
    before += wrongs[c - 1];
    if (c < WINDOW_MIN_OLD) continue;
    const k = total - before, q = (n - c) / n;
    const p = 2 * Math.min(binomCdf(k, total, q), 1 - binomCdf(k - 1, total, q));
    if (p < best) { best = p; at = c; }
  }
  return best < WINDOW_ALPHA ? at : 0;
}
function mockAllSheets() {
  return loadExamHistory().filter(r => r.total > 0 && (r.level == null || r.level === EXAM_LEVEL));
}
function mockRecentSheets(windowN) {
  const all = mockAllSheets();
  if (windowN != null) return all.slice(0, windowN);
  const start = mockWindowStart(all.map(sheetWrong).reverse());
  return all.slice(0, all.length - start);
}

function mockRecentForm(windowN = null, minN = READY_MIN_MOCKS) {
  const recent = mockRecentSheets(windowN);
  // Two sheets set a mean and a spread from two numbers, and this line is a
  // claim about the exam the learner is going to sit; the maintainer kept the
  // floor at three on 2026-09-21 rather than let the t price the thinness. The
  // render says how many more are wanted, since the alternative is a reader
  // looking for a line that is simply not drawn (reported that day).
  if (recent.length < minN) return null;
  return mockFormFrom(recent.map(sheetWrong));
}
// The prediction itself, from a list of wrong-counts (two or more).
// `sMin` keeps the spread from falling below a given value. The projection
// passes the learner's own measured spread, so the identical sheets it adds
// do not make the learner look steadier than they have been.
function mockFormFrom(wrongs, sMin = 0) {
  const n    = wrongs.length;
  const mean = wrongs.reduce((a, w) => a + w, 0) / n;
  const sObs = Math.sqrt(wrongs.reduce((a, w) => a + (w - mean) * (w - mean), 0) / (n - 1));
  // The sheet's own sampling noise, the floor described above.
  const p     = Math.min(1, Math.max(0, 1 - mean / EXAM_QUESTION_COUNT));
  const floor = Math.sqrt(EXAM_QUESTION_COUNT * p * (1 - p));
  const s     = Math.max(sObs, floor, sMin);
  const se    = s * Math.sqrt(1 + 1 / n);
  const chance = se > 0 ? studentT((EXAM_MAX_WRONG + 0.5 - mean) / se, n - 1)
                        : (mean <= EXAM_MAX_WRONG ? 1 : 0);
  const passed = wrongs.filter(w => w <= EXAM_MAX_WRONG).length;
  return { n, mean, sObs, s, chance, passed, worst: Math.max(...wrongs) };
}

// The count of further mock exams to the 5% bar was REMOVED in 20261009w
// (maintainer, 2026-10-03). Replayed over his 26 mocks it read 32, 8,
// never, 27, 23, 7, 15, 1 while the chance of failing fell steadily: near
// the bar the count is hypersensitive to the last few scores, so it cannot
// be predicted well and is not mentioned. With mocks on record the block
// gives no date and names the bar; with none, the flat allowance stands.

function renderDashboard() {
  if (!questions.length) return;
  // Every level cleared: the compact dashboard, unless Settings asks for the
  // full one. The weak spots and the mock exam both run at Italiano and the
  // level buttons are hidden, so the active level is put there first, before
  // anything below reads `progress`.
  _dashCompact = italianoComplete() && !dashFullOn();
  if (_dashCompact && currentLevel !== EXAM_LEVEL && !midActivity()) setLevel(EXAM_LEVEL);
  document.getElementById('screen-dashboard')?.classList.toggle('dash-compact', _dashCompact);
  updateResumeButton();

  const { total, cleared, qTotal, qCleared } = countCards(progress);

  // Which Reference tabs exist is reviewSectionsAvailable()'s decision alone,
  // applied by applyReviewSection() whenever that screen renders (showScreen
  // calls it on every entry). The dashboard used to toggle the Vocabulary tab
  // here as well, which meant two places deciding one button.

  // The mock exam, and therefore readiness, exists only in Italiano (it
  // mirrors the real, Italian-only exam). The dashboard keeps only the
  // 'ready' banner; the average itself lives on the Exam Prep screen.
  const rd = examReady();

  // Linear card-clearing progress bar — shown at every level.
  const cpBar = document.getElementById('cards-progress-bar');
  const cpLabel = document.getElementById('cards-progress-label');
  const cpPct = total ? Math.round((cleared / total) * 100) : 0;
  if (cpBar) cpBar.style.width = (cleared > 0 ? Math.max(2, cpPct) : 0) + '%';
  if (cpLabel) cpLabel.textContent = t('dash.cardsProgress', cleared.toLocaleString(), total.toLocaleString(), cpPct);
  // Second line: the same progress counted in individual questions.
  const cpQ = document.getElementById('cards-progress-qlabel');
  if (cpQ) cpQ.textContent = t('dash.questionsProgress', qCleared.toLocaleString(), qTotal.toLocaleString());

  const banner = document.getElementById('exam-ready-banner');
  if (banner) {
    // The text is drawn here, with the real chance and count, so the static
    // markup's translation must not repaint it.
    banner.removeAttribute('data-i18n-html');
    // Once a mock is on record the banner also says when the learner is NOT
    // yet at the bar, and what is missing (20261007x, maintainer, 2026-10-02):
    // too few mocks, a chance of failing over the target, or weak spots still
    // open. With no result on record (or all of them cleared) it is hidden.
    const target = Math.round((1 - READY_BANNER_CHANCE) * 100);
    // Weak spots still open no longer make the banner a warning (20261009x,
    // maintainer, 2026-10-03): at the bar the learner IS ready, and the
    // weak spots are a suggestion. A ready banner also says what comes
    // next: the school's own mock exams, and staying prepared.
    const atBar = rd.taken >= READY_BANNER_MOCKS && rd.chance != null && rd.chance >= READY_BANNER_CHANCE;
    const text = rd.taken === 0 ? ''
      : rd.taken < READY_BANNER_MOCKS ? t('banner.fewMocks', rd.taken, READY_BANNER_MOCKS)
      : !atBar ? t('banner.notYet', failPctText(rd.chance), rd.n, target)
      : (rd.weak > 0 ? t('banner.weakOpen', failPctText(rd.chance), rd.n, rd.weak) : t('banner.readyNow', failPctText(rd.chance), rd.n))
        + ' ' + t('banner.readyNext');
    // With an exam date entered the ready banner goes (20261009z,
    // maintainer): the countdown box under it carries this phase. A
    // warning still shows.
    // After the exam (20261029l) the box says what comes next, and the
    // banner, which is about readiness for the exam, goes.
    banner.classList.toggle('hidden', !text || (atBar && !!examDate()) || !!examAfterState());
    banner.classList.toggle('banner-success', atBar);
    banner.classList.toggle('banner-warn', !atBar);
    banner.textContent = text;
    try { renderExamDate(atBar); } catch (e) { console.error('exam date:', e); }
  }


  // Isolate each section so one failing piece can't blank the whole dashboard.
  try { maybeShowBackupBanner(); }  catch (e) { console.error('backup banner:', e); }
  try { hideWipBanner(); }         catch (e) { console.error('wip banner:', e); }
  try { ensureAboutLink(); }       catch (e) { console.error('about link:', e); }
  try { ensureCreditsLink(); }     catch (e) { console.error('credits link:', e); }
  try { ensureSourceLink(); }      catch (e) { console.error('source link:', e); }
  try { maybeShowInstallBanner(); } catch (e) { console.error('install banner:', e); }
  try { renderLevelSelector(); }    catch (e) { console.error('level selector:', e); }
  try { renderSessionSummary(); }   catch (e) { console.error('session summary:', e); }
  try { renderWeakSpots(); }        catch (e) { console.error('weak spots:', e); }
  try { renderDailyLoop(); } catch (e) { console.error('daily loop:', e); }
  try { renderTopicProgress('topic-progress-grid'); } catch (e) { console.error('topic grid:', e); }
  try { paintTopicHeading(); }      catch (e) { console.error('topic heading:', e); }
  try { renderReviewerFlags(); }    catch (e) { console.error('reviewer flags:', e); }
}

// The grid's heading says what the grid is: progress while the levels are
// worked, the Concepts once they are cleared. A second heading built in JS
// rather than a rewritten data-i18n one, which applyI18n would repaint.
function paintTopicHeading() {
  const grid = document.getElementById('topic-progress-grid');
  const orig = document.querySelector('[data-i18n="dash.progressByTopic"]');
  if (!grid) return;
  let h = document.getElementById('dash-topics-concepts');
  if (!h) {
    h = document.createElement('h2');
    h.id = 'dash-topics-concepts';
    h.className = 'section-title';
    grid.parentNode.insertBefore(h, grid);
  }
  h.textContent = t('dash.topicConcepts');
  h.classList.toggle('hidden', !_dashCompact);
  if (orig) orig.classList.toggle('hidden', _dashCompact);
  // The key points of every topic, offered at every stage (20261029m).
  let kp = document.getElementById('dash-keypoints');
  if (!kp) {
    kp = document.createElement('p');
    kp.id = 'dash-keypoints';
    kp.className = 'dash-keypoints';
    kp.innerHTML = '<button type="button" class="link-btn"></button>';
    kp.querySelector('button').addEventListener('click', openKeyPoints);
    grid.parentNode.insertBefore(kp, grid);
  }
  let m = 0; try { m = keyPointsMinutes(uiLang() === 'it' ? 'it' : 'en'); } catch { }
  kp.querySelector('button').textContent = t('keypoints.link', m);
  kp.classList.toggle('hidden', !m);
}

// Every active statement cleared at Italiano: the bank is finished at the
// level the exam tests. (cardCleared reads the live level; this reads L3
// directly so it answers the same question from any level.)
function italianoComplete() {
  const p3 = loadProgressForLevel(EXAM_LEVEL);
  for (const q of questions) {
    const act = activeStatements(q.id);
    if (!act.length) continue;
    for (const s of act) if (!isStmtMastered(p3[q.id]?.st?.[s.number])) return false;
  }
  return true;
}

// Weak spots as a first-class study mode. The pre-exam drill has always
// existed, but it lived on the exam page, so a learner working the dashboard
// never met it. This card puts it above the topic grid, names the topics the
// misses cluster in, and starts the same drill.
//
// It appears only once Italiano is COMPLETE. While the bank is still being
// worked, misses are simply the work in progress, and a card announcing
// "203 questions you keep missing" is a discouragement, not a study mode.
// Once every card is cleared at the exam level, the same list becomes the
// natural next thing to do, which is when the card earns its place. (The
// exam-page entry keeps its older, looser rule for anyone who goes looking.)
function renderWeakSpots() {
  const box = document.getElementById('weak-spots');
  if (!box) return;
  // Above the level buttons (maintainer, 2026-09-30): once every level is
  // cleared the drill is the work, so it leads the dashboard. Moved in JS as
  // well as in index.html, because a stale cached page carries the old order.
  // It sits in a row with the mock exam card (maintainer, 2026-10-01), and
  // once the levels are cleared it STAYS, saying there are none, since mock
  // exam misses bring weak spots back.
  const complete = currentLevel > 1 && italianoComplete();
  // Once the theory exam is passed (20261029l) nothing asks for mock exams
  // or weak spots.
  const mockShow = (complete || mockEarlyOn()) && !theoryPassed();
  const wrap = ensureDashNext();
  wrap.classList.toggle('hidden', !mockShow);
  wrap.classList.toggle('is-single', !complete);
  renderDashMock(mockShow);
  const ranked = complete ? difficultCards() : [];
  const n = ranked.reduce((acc, d) => acc + d.stmts.length, 0);
  // With an exam date entered the weak spots are part of the daily review
  // (20261010c), so their own card goes.
  const inReview = complete && !!examDate();
  box.classList.toggle('hidden', !complete || inReview);
  wrap.classList.toggle('is-single', !complete || inReview);
  if (!complete || inReview) return;
  const btn = document.getElementById('btn-weak-spots');
  box.classList.toggle('is-empty', n === 0);
  btn.classList.toggle('hidden', n === 0);
  if (n === 0) {
    document.getElementById('weak-title').textContent = t('weak.none');
    document.getElementById('weak-sub').textContent = t('weak.noneSub');
    return;
  }
  // Topics where the misses cluster, by drill weight, top three.
  const byTopic = new Map();
  for (const d of ranked) byTopic.set(d.topic, (byTopic.get(d.topic) || 0) + d.weight);
  const top = [...byTopic.entries()].sort((a, b) => b[1] - a[1]).slice(0, 3).map(([tp]) => topicShort(tp));
  const list = top.length <= 1 ? top.join('') : top.slice(0, -1).join(', ') + t('weak.and') + top[top.length - 1];
  document.getElementById('weak-title').textContent = t('weak.title', n.toLocaleString());
  const eff = drillEffort();
  const sub = [top.length ? t('weak.mostly', list) : ''];
  if (eff) {
    sub.push(eff.days != null
      ? t('weak.effort', eff.answers.toLocaleString(), drillSpanWords(eff), t('lvl.3.name'))
      : t('weak.effortNoPace', eff.answers.toLocaleString(), '', t('lvl.3.name')));
  }
  if (currentLevel !== EXAM_LEVEL) sub.push(t('drill.inItaliano'));
  document.getElementById('weak-sub').textContent = sub.filter(Boolean).join(' ');
  btn.textContent = t('drill.start', n.toLocaleString());
  btn.onclick = startDrill;
}

// The row above the level buttons that holds the weak spots and the mock exam
// card, side by side on a wide screen. Built in JS, since index.html is cached
// separately and a stale page has neither the row nor the card.
function ensureDashNext() {
  let wrap = document.getElementById('dash-next');
  const weak = document.getElementById('weak-spots');
  const sel = document.getElementById('level-selector');
  if (!wrap) {
    wrap = document.createElement('div');
    wrap.id = 'dash-next';
    wrap.className = 'dash-next hidden';
    const mock = document.createElement('div');
    mock.id = 'dash-mock';
    mock.className = 'weak-spots dash-mock';
    mock.innerHTML = '<div class="weak-text"><div class="weak-title" id="dash-mock-title"></div>' +
                     '<div class="weak-sub" id="dash-mock-sub"></div></div>' +
                     '<button type="button" id="btn-dash-mock" class="btn-primary"></button>';
    mock.querySelector('button').addEventListener('click', startMockFromDashboard);
    wrap.appendChild(mock);
  }
  if (sel && wrap.nextElementSibling !== sel) sel.parentNode.insertBefore(wrap, sel);
  if (weak && weak.parentNode !== wrap) wrap.insertBefore(weak, wrap.firstChild);
  return wrap;
}

function renderDashMock(show) {
  const card = document.getElementById('dash-mock');
  if (!card) return;
  card.classList.toggle('hidden', !show);
  if (!show) return;
  // In the review stage the pace is one mock a day (20261011i, maintainer,
  // 2026-10-04): once today's is taken the card says so, and the button
  // stays, quieter, for a learner who wants another.
  let doneToday = false;
  try { doneToday = inReviewPhase() && loadExamHistory().some(r => dayKey(new Date(r.date)) === dayKey()); } catch { }
  card.classList.toggle('is-done', doneToday);
  document.getElementById('dash-mock-title').textContent = t(doneToday ? 'dash.mockDoneTitle' : 'dash.mockTitle');
  document.getElementById('dash-mock-sub').textContent = t(doneToday ? 'dash.mockDoneSub' : 'dash.mockSub');
  const btn = document.getElementById('btn-dash-mock');
  btn.textContent = t(doneToday ? 'dash.mockAgain' : 'dash.mockStart');
  btn.className = doneToday ? 'btn-secondary' : 'btn-primary';
}

// A full simulation of the exam room (maintainer, 2026-10-01). The sheet
// opens BLANK under a modal that says the exam takes 20 minutes, cannot be
// paused, and is lost if the learner leaves; the clock starts only on Start.
// From that moment the nav is locked (`exam-locked` on the body), so nothing
// can be looked up, and the app icon is the one way out, after a
// confirmation. The sheet lives on the Statistics screen, where the result
// is shown.
function startMockFromDashboard() {
  if (currentLevel !== EXAM_LEVEL) setLevel(EXAM_LEVEL);
  const nav = document.querySelector('.nav-btn[data-screen="exam"]');
  if (nav) nav.click(); else showScreen('screen-exam');
  document.getElementById('exam-start').classList.add('hidden');
  document.getElementById('exam-results').classList.add('hidden');
  document.getElementById('exam-timer').classList.add('hidden');
  ensureExamSheet();
  document.getElementById('exam-summary')?.classList.add('hidden');
  document.getElementById('exam-sheet')?.classList.remove('hidden');
  examState.secondsLeft = EXAM_SECONDS;
  updateTimerDisplay();
  const prog = document.getElementById('exam-in-progress');
  prog.classList.remove('hidden');
  prog.classList.add('is-veiled');
  document.body.classList.add('exam-locked');
  window.scrollTo(0, 0);
  const ov = ensureMockIntro();
  document.getElementById('mock-intro-title').textContent = t('mock.introTitle');
  document.getElementById('mock-intro-line').textContent  = t('mock.introLine');
  const tipEl = document.getElementById('mock-intro-tip'); if (tipEl) tipEl.textContent = t('mock.introTip');
  const go = document.getElementById('mock-intro-start');
  const no = document.getElementById('mock-intro-cancel');
  go.textContent = t('mock.start');
  no.textContent = t('mock.notNow');
  const close = () => { ov.classList.add('hidden'); unlockBodyScroll(); };
  go.onclick = () => { close(); prog.classList.remove('is-veiled'); startExam(); };
  no.onclick = () => { close(); abandonExam(); };
  ov.classList.remove('hidden');   // no backdrop close: the learner chooses
  lockBodyScroll();
  focusModal(ov);
}

function ensureMockIntro() {
  let ov = document.getElementById('mock-intro-overlay');
  if (ov) return ov;
  ov = document.createElement('div');
  ov.id = 'mock-intro-overlay';
  ov.className = 'review-overlay hidden';
  ov.innerHTML = '<div class="review-dialog goal-dialog" role="dialog" aria-modal="true" aria-labelledby="mock-intro-title" tabindex="-1">' +
    '<h2 id="mock-intro-title" class="review-title"></h2><p id="mock-intro-line" class="goal-line"></p><p id="mock-intro-tip" class="goal-line"></p>' +
    '<div class="goal-actions"><button type="button" id="mock-intro-start" class="btn-primary"></button>' +
    '<button type="button" id="mock-intro-cancel" class="btn-ghost"></button></div></div>';
  document.body.appendChild(ov);
  return ov;
}

// Leaving a mock before it is closed: nothing is saved, nothing feeds the weak
// spots, and the learner is back on the main page.
function abandonExam() {
  clearInterval(examState.timerHandle);
  examState.timerHandle = null;
  examState.items = [];
  examState.answers = [];
  document.getElementById('mock-intro-overlay')?.classList.add('hidden');
  const prog = document.getElementById('exam-in-progress');
  prog.classList.add('hidden');
  prog.classList.remove('is-veiled');
  document.getElementById('exam-start').classList.remove('hidden');
  document.body.classList.remove('exam-locked');
  showScreen('dashboard');
  renderDashboard();
  setNavActive('dashboard');
  window.scrollTo(0, 0);
}

// The Settings row for the full dashboard, built when a stale cached
// index.html lacks it. English in the markup, Italian in STATIC_IT, like the
// rows written in index.html.
// Settings grouped by the stage of the learner's path (20261011f, maintainer,
// 2026-10-04; see "The stages" in CLAUDE.md). A group for a stage not yet
// reached is hidden; past and current ones stay. Built here, by moving the
// existing rows, so a stale cached index.html is grouped the same way.
// Your data comes FIRST (20261013b, maintainer, 2026-10-14): sync is the
// first thing a learner does on a new device, the one group that applies at
// every stage, and where the dashboard's backup banner sends people. The
// stage groups follow in the order of the learner's path, Reviewers last.
// Rows are appended in the order listed here, so the order inside a group
// is this list's order, not index.html's.
const SETTINGS_GROUPS = [
  { id: 'sg-data',     key: 'settings.grpData',     en: 'Your data',
    nodes: ['settings-sync', 'settings-backup'] },
  { id: 'sg-answer',   key: 'settings.grpAnswer',   en: 'While you answer',
    rows: ['set-sound', 'set-ignore-silent', 'set-vibrate', 'set-tts-rate', 'set-expl-correct', 'set-autoscroll'] },
  // Abridged mode decides WHAT is studied, so it leads; the note at the top
  // of the topic notes governs the Concepts, study material rather than
  // answering; the early-mock option bridges to the next stage, so it closes.
  { id: 'sg-levels',   key: 'settings.grpLevels',   en: 'Studying the levels',
    rows: ['set-abridged', 'set-english-only', 'set-review-note', 'set-mock-early'] },
  { id: 'sg-after',    key: 'settings.grpAfter',    en: 'Weak spots and mock exams',
    rows: ['set-dash-full', 'set-exam-mix'] },
  { id: 'sg-review',   key: 'settings.grpReview',   en: 'Before your exam',
    rows: ['set-review-expl'] },
  { id: 'sg-reviewer', key: 'settings.grpReviewer', en: 'Reviewers',
    rows: ['set-reviewer', 'set-reviewer-code'] },
];
function ensureSettingsGroups() {
  const body = document.querySelector('#settings-overlay .settings-body');
  if (!body) return;
  for (const g of SETTINGS_GROUPS) {
    let sec = document.getElementById(g.id);
    if (!sec) {
      sec = document.createElement('section');
      sec.id = g.id;
      sec.className = 'settings-group';
      sec.innerHTML = `<h3 class="settings-group-head" data-i18n="${g.key}">${g.en}</h3>`;
    }
    body.appendChild(sec);
    const els = (g.rows || []).map(id => {
      const el = document.getElementById(id);
      return el && (el.closest('.settings-row') || el.closest('label') || el);
    }).concat((g.nodes || []).map(id => document.getElementById(id)));
    for (const el of els) if (el && el.parentNode !== sec) { el.classList.remove('settings-divide'); sec.appendChild(el); }
  }
}
function updateSettingsGroups() {
  let after = false, review = false;
  try { after = italianoComplete() || mockEarlyOn(); } catch { }
  try { review = inReviewPhase(); } catch { }
  document.getElementById('sg-after')?.classList.toggle('hidden', !after);
  document.getElementById('sg-review')?.classList.toggle('hidden', !review);
}
function ensureDashFullRow() {
  const add = (id, afterId, key, title, desc) => {
    if (document.getElementById(id)) return;
    const after = document.getElementById(afterId)?.closest('label');
    if (!after) return;
    const row = document.createElement('label');
    row.className = 'settings-row';
    row.innerHTML = '<input type="checkbox" id="' + id + '"><span class="settings-row-text">' +
      '<span class="settings-row-title" data-i18n="' + key + '">' + title + '</span>' +
      '<span class="settings-row-desc" data-i18n="' + key + 'Desc">' + desc + '</span></span>';
    after.after(row);
  };
  add('set-dash-full', 'set-review-note', 'settings.dashFull', '📊 Show the levels and topic progress',
      'Once every level is cleared, the main page hides the level buttons and the progress of each topic, and leads with the weak spots and the mock exam. Turn this on to see them again.');
  add('set-review-expl', 'set-expl-correct', 'settings.reviewExpl', '📖 In the review, show the explanation and translation after a correct answer',
      'In the daily review the explanation and the English translation open after every answer, right or wrong. It applies to the review only.');
  add('set-mock-early', 'set-dash-full', 'settings.mockEarly', '📝 Show the mock exam before the levels are cleared',
      'Adds the mock exam card to the main page while you are still working through the levels. Once every level is cleared it is always there.');
}

// A number of days in words: "one day", "12 days", "6 weeks", "9 months".
// `tr` lets a caller pick the translator: t() follows the study level, vt()
// follows the reader's language on the Reference screen.
function spanInWords(dd, tr = t) {
  return dd <= 1 ? tr('daily.day1')
       : dd <= 21 ? tr('daily.days', dd)
       : dd <= 120 ? tr('daily.weeks', Math.round(dd / 7))
       : tr('daily.months', Math.round(dd / 30));
}

// The average line: correct answers per study day over the recent window.
function dailyRateLine(r) {
  const rate = Math.round(r.perStudyDay || r.rate);
  const rested = r.studied < r.days;
  return r.days <= 1 ? t('daily.rateOneDay', rate.toLocaleString())
       : rested ? (r.days - r.studied === 1
                    ? t('daily.rateRest1', rate.toLocaleString(), r.studied.toLocaleString())
                    : t('daily.rateRest', rate.toLocaleString(), r.studied.toLocaleString(), (r.days - r.studied).toLocaleString()))
       : t('daily.rate', rate.toLocaleString(), r.days.toLocaleString());
}

function renderDailyLoop() {
  const wrap = document.getElementById('daily-loop');
  if (!wrap) return;
  const log   = loadDaily();
  const today = dailyProgress(log[dayKey()]);
  const r     = studyRate(log);

  // The ring holds today's count and nothing else. It used to fill toward a
  // goal and turn red below three quarters of it, which made a short day look
  // like a failure; there is no target now, so there is no arc to fill.
  const num = document.getElementById('daily-ring-num');
  if (num) num.textContent = String(today);

  const title = document.getElementById('daily-title');
  if (title) title.textContent = t('daily.todayCount', today.toLocaleString());

  // Strip: oldest on the left, today on the right, one dot per calendar day.
  // A dot's weight says how much was done RELATIVE TO THIS LEARNER'S OWN
  // average day, not to a quota: empty for a rest day, then three steps up.
  // Nothing here can be "missed".
  const strip = document.getElementById('daily-strip');
  if (strip) {
    strip.title = t('daily.stripHint');
    const fmt = new Intl.DateTimeFormat(uiLang() === 'it' ? 'it-IT' : 'en-US', { month: 'short', day: 'numeric' });
    const base = r && r.rate > 0 ? r.rate : 1;
    let html = '';
    for (let i = 13; i >= 0; i--) {
      const rec = log[dayKeyOffset(i)];
      const a = dailyProgress(rec);
      // Answered but cleared nothing new: re-drilling a statement already
      // cleared, or missing what was attempted. Work, not a rest day, so it
      // gets its own faint dot rather than the empty one.
      const worked = a <= 0 && (rec?.a || 0) > 0;
      const cls = a <= 0 ? (worked ? 'ew' : 'e0')
                : a >= base * 1.25 ? 'e3' : a >= base * 0.5 ? 'e2' : 'e1';
      const d = new Date(); d.setDate(d.getDate() - i);
      const when = i === 0 ? t('daily.todayWord') : fmt.format(d);
      const tip = a > 0 ? t('daily.dotDid', when, a.toLocaleString())
                : worked ? t('daily.dotNoNew', when, (rec.a || 0).toLocaleString())
                : t('daily.dotNone', when);
      html += `<span class="daily-dot ${cls}${i === 0 ? ' today' : ''}" title="${escHtml(tip)}"></span>`;
    }
    strip.innerHTML = html;
  }
  // Days in a row with any study. A record of showing up, and it says nothing
  // about how much was done on each.
  const streak = dailyStreak(log);
  const sEl = document.getElementById('daily-streak');
  if (sEl) { sEl.textContent = streak >= 2 ? t('daily.streak', streak) : ''; sEl.classList.toggle('hidden', streak < 2); }

  // Two lines of plain description: the rate the learner is actually working
  // at, and where that rate leads. No target, no deadline, so a quiet day
  // moves the date rather than failing anything.
  const proj = document.getElementById('daily-projection');
  if (proj) {
    const multi = countedLevels().length > 1;
    const left  = remainingAcrossLevels();
    // Every branch below puts ESCAPED HTML into `lines`, not plain text. One
    // of them interpolates an anchor into its sentence, so the join at the
    // bottom cannot escape for them.
    let lines;
    if (left <= 0) {
      // The material is finished, but ready means ready to take the exam, so
      // say what the reserve still holds rather than stopping at "cleared".
      //
      // It still gives a DATE (maintainer, 2026-09-29: finishing the levels
      // took the date away, which is the moment it matters most). The date
      // is today plus what is left: the weak spots at the learner's own pace,
      // and the mock allowance unless the recent mocks already clear the
      // readiness bar. With nothing left the line says so, still linked.
      lines = [escHtml(t(multi ? 'daily.done3' : 'daily.done'))];
      // The average stays on screen after the levels are done (maintainer,
      // 2026-09-30): it is the pace the date below is computed from, and the
      // weak-spot answers now count in it.
      const rl = r && r.rate > 0 ? dailyRateLine(r) : null;
      if (rl) lines.push(escHtml(rl));
      const parts = reserveParts(log);
      const drillDays = parts ? parts.drill : 0;
      // With mocks on record and the bar not met, the block gives NO date
      // (20261009w): how many more mocks it takes cannot be predicted well.
      // With none on record the flat allowance stands, as before.
      const rdy  = examReady();
      const far  = !rdy.ready && rdy.taken > 0 && !(rdy.chance != null && rdy.chance >= READY_BANNER_CHANCE);
      const drillWords = drillSpanWords(drillEffort(log)) || spanInWords(drillDays);
      const mockDays = (rdy.ready || far || (rdy.chance != null && rdy.chance >= READY_BANNER_CHANCE)) ? 0 : (parts ? parts.mocks : MOCK_EXAM_DAYS);
      // In the review stage nothing remains in this sense: the weak spots are
      // folded into the day's review, and the exam date box says what to do
      // each day (20261011k, maintainer).
      if (inReviewPhase()) { /* the exam date box carries the day's work */ }
      else if (far) lines.push(escHtml(drillDays > 0 ? t('daily.doneLeftOpen', drillWords) : t('daily.doneMocksOpen')));
      else if (drillDays > 0 && mockDays > 0) lines.push(escHtml(t('daily.doneLeft', drillWords, spanInWords(mockDays))));
      else if (drillDays > 0) lines.push(escHtml(t('daily.doneLeftDrill', drillWords)));
      else if (mockDays > 0)  lines.push(escHtml(t('daily.doneLeftMocks', spanInWords(mockDays))));
      const readyWordD = `<a href="#" class="exam-plan-step">${escHtml(t('daily.readyWord'))}</a>`;
      // Weak spots that take under DRILL_FITS_MIN minutes add no day of
      // their own when mock days are already counted: they fit in the first
      // of those (20261009f, maintainer: six minutes of weak spots made a
      // four-day estimate read five).
      const effD = drillEffort(log);
      const drillFits = mockDays > 0 && effD && effD.minutes < DRILL_FITS_MIN && (effD.days == null || effD.days <= 1);
      const dd = (drillFits ? 0 : drillDays) + mockDays;
      // With an exam date entered the block projects no ready date
      // (20261010a, maintainer): the countdown box says when the exam is.
      if (far || examDate()) { /* no date */ }
      else if (dd <= 0) lines.push(t('daily.readyNow', readyWordD));
      else {
        const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() + dd);
        const fmtD = new Intl.DateTimeFormat(uiLang() === 'it' ? 'it-IT' : 'en-US',
          d.getFullYear() !== new Date().getFullYear() ? { month: 'short', day: 'numeric', year: 'numeric' } : { month: 'short', day: 'numeric' });
        lines.push(t('daily.readyDone', readyWordD, escHtml(fmtD.format(d)), escHtml(spanInWords(dd))));
      }
    } else if (!r || r.rate <= 0) {
      lines = [escHtml(t('daily.noPace'))];
    } else {
      const rested = r.studied < r.days;
      const ready  = readyDate(log);
      const dd     = daysUntilReady(log);
      const ready5 = readyDate(log, true);
      const dd5    = daysUntilReady(log, true);
      // A date in another year carries its year, or "Mar 12" reads as next
      // spring when it means several springs away. Both dates get the year
      // if either needs it, so the two never read in different formats.
      const thisYear = new Date().getFullYear();
      const other = [ready, ready5].some(d => d && d.getFullYear() !== thisYear);
      const fmt  = new Intl.DateTimeFormat(uiLang() === 'it' ? 'it-IT' : 'en-US',
        other ? { month: 'short', day: 'numeric', year: 'numeric' }
              : { month: 'short', day: 'numeric' });
      // Both dates are printed whenever the five-day one exists and is itself
      // inside the year the first date has to be inside. Keyed on the date
      // rather than on whether the learner rested, so the sentence and the
      // number of dates in it can never disagree.
      const both = ready5 != null && dd5 != null && dd5 <= 365;
      // The block used to say "ready" and never say what for, and the reader
      // supplies "ready for the next step", which depends on where they are
      // (reported 2026-09-21). So the date sentence itself reads "you would be
      // READY for the exam around Oct 8", with that one word linking into the
      // How-to at step 4. It is inside the sentence, at the maintainer's
      // direction, rather than a line of its own underneath: a separate
      // sentence explaining the word was his first version of this and he
      // replaced it, since the sentence can simply say it.
      //
      // The paperwork used to be printed here instead, as a paragraph about
      // booking the medical appointments, and he cut that the same day: this
      // block projects a study date, and the PROCESS of getting a license
      // belongs in the How-to panel, which is the authority on it. Do not
      // bring a process paragraph back here; add it to the How-to and let
      // this link point at it.
      const readyWord = `<a href="#" class="exam-plan-step">${escHtml(t('daily.readyWord'))}</a>`;
      const D = d => escHtml(fmt.format(d));
      lines = [
        escHtml(dailyRateLine(r)),
        // No date from a partial first day: five answers over breakfast
        // extrapolate to a decade, which is noise dressed as a forecast. And
        // no date past a year: at that distance the figure says nothing a
        // learner can use, while the sentence explaining what moves it does.
        // Neither of those two carries the link, since neither promises a date
        // and there is nothing to be ready for.
        r.partial          ? escHtml(t('daily.readyAfterDay'))
        : dd > 365         ? escHtml(t('daily.readyFar'))
        : both             ? t(rested ? 'daily.readyRest' : 'daily.readyDaily',
                               readyWord, D(ready), escHtml(spanInWords(dd)),
                               D(ready5), escHtml(spanInWords(dd5)))
        : t('daily.ready', readyWord, D(ready), escHtml(spanInWords(dd))),
      ];
      // Third line: what the reserve at the end is made of. Only when the
      // date itself was printed, since the other two branches say no date.
      if (!r.partial && dd <= 365) {
        const parts = reserveParts(log);
        lines.push(escHtml(parts
          ? t(both ? 'daily.reserveSplit' : 'daily.reserveOne',
              spanInWords(parts.drill), spanInWords(parts.mocks))
          : t('daily.reserveFlat')));
      }
    }
    // `lines` holds HTML, not text: every branch above escapes its own pieces,
    // because one of them interpolates an anchor and a blanket escHtml here
    // would print the markup. Escape at the point a value is put in, and if a
    // new line is added to this block, escape it there too.
    proj.innerHTML = lines.map(l => `<div class="exam-plan-line">${l}</div>`).join('');
  }
}

// The projection's "the theory exam" link opens the How-to panel at step 4,
// which is the step the ready date is about.
//
// Delegated on the document rather than bound in renderDaily, because that
// function rewrites its own innerHTML on every render and a listener on the
// anchor would leak one per repaint. The panel is a sibling further down the
// same screen, so this only has to open the disclosure and scroll.
//
// The How-to is found by its SUMMARY's translation key, never by
// `details.rules-note`: there are two of those on the dashboard and the other
// one, "How to use this app", sits first. The theory-exam step is found by its
// CLASS, `step-theory`, in the route tab showing (20261007c), since the steps
// carry no ids: the whole panel is one `data-i18n-html` block repainted per
// language, and a class written into both languages' markup survives the
// paint where an id would collide between the two tabs. Before the tabs it
// was found by position, step 4; that is kept as the fallback for a stale
// cached English page.
document.addEventListener('click', (e) => {
  const a = e.target.closest('.exam-plan-step');
  if (!a) return;
  e.preventDefault();
  const sum = document.querySelector('[data-i18n="next.summary"]');
  const box = sum && sum.closest('details');
  if (!box) return;
  box.open = true;
  // The list has to be laid out before a step can be scrolled to, and the
  // browser lays the panel out only once `open` is set, so wait a frame.
  requestAnimationFrame(() => {
    const step = box.querySelector('.route-pane:not(.hidden) li.step-theory') || box.querySelector('ol > li:nth-child(4)') || sum;
    step.scrollIntoView({ behavior: 'smooth', block: 'center' });
  });
});

// Summary of the session the learner just left, shown once at the top of the
// dashboard and dismissed by tap or by starting the next session. Personal
// best is judged against every previous day.
function renderSessionSummary() {
  const el = document.getElementById('session-summary');
  if (!el) return;
  if (_sess.shown || _sess.a === 0) { el.classList.add('hidden'); return; }
  const log = loadDaily();
  const todayA = log[dayKey()]?.a || 0;
  const prevBest = Math.max(0, ...Object.entries(log).filter(([k]) => k !== dayKey()).map(([, d]) => d.a || 0));
  const pct = Math.round((_sess.c / _sess.a) * 100);
  let html = `<div class="sess-title">${escHtml(t('sess.title'))}</div>` +
             `<div class="sess-line">${escHtml(t('sess.line', _sess.a.toLocaleString(), pct, _sess.bestRun))}</div>`;
  if (_sess.cards > 0) html += `<div class="sess-line">${escHtml(_sess.cards === 1 ? t('sess.cards1') : t('sess.cards', _sess.cards))}</div>`;
  // Time per question, from the answers this session that gave a usable
  // reading (see ANSWER_MAX_MS): a handful is enough to be worth showing.
  if (_sess.timed >= 5) {
    const secs = (_sess.ms / _sess.timed) / 1000;
    html += `<div class="sess-line">${escHtml(t('sess.pace', secs < 10 ? secs.toFixed(1) : String(Math.round(secs))))}</div>`;
  }
  if (todayA > prevBest && prevBest > 0) html += `<div class="sess-record">🏆 ${escHtml(t('sess.record', todayA.toLocaleString()))}</div>`;
  html += `<button type="button" class="banner-dismiss" id="sess-dismiss" aria-label="${escHtml(t('sess.dismiss'))}">✕</button>`;
  el.innerHTML = html;
  el.classList.remove('hidden');
  _sess.seen = true;   // the next study session starts a fresh summary
  el.querySelector('#sess-dismiss')?.addEventListener('click', () => { sessReset(); el.classList.add('hidden'); });
}

// Bottom-of-dashboard flagged-issue actions, shown only in Reviewer mode. The
// Export control is always visible (disabled at 0) so it's discoverable; Clear
// appears only when there's something to remove.
function renderReviewerFlags() {
  const wrap = document.getElementById('dashboard-flags');
  if (!wrap) return;
  if (!devMode()) { wrap.classList.add('hidden'); return; }
  wrap.classList.remove('hidden');
  // `all` counts every comment kept, sent or not; `n` counts the ones a Send
  // would post. The review button opens on either, since the Sent list is
  // worth reading on its own.
  const all = loadFlags().length, n = unsentFlags().length;
  const rev = document.getElementById('btn-review-flags');
  if (rev) { rev.textContent = t('flags.review', n); rev.disabled = (all === 0); }
  const send = document.getElementById('btn-send-flags');
  if (send) { send.textContent = t('settings.sendFlags', n); send.disabled = (n === 0); }
  const exp = document.getElementById('btn-export-flags');
  if (exp) { exp.textContent = t('settings.exportFlags', all); exp.disabled = (all === 0); }
  const clr = document.getElementById('btn-clear-flags');
  if (clr) clr.classList.toggle('hidden', n === 0);
}

// ── "Install to home screen / dock" nudge ─────────────────────────────
function isAppInstalled() {
  // iOS standalone web app, or any platform launched in standalone display mode
  return window.navigator.standalone === true ||
         window.matchMedia?.('(display-mode: standalone)').matches === true;
}

function installInstructionText() {
  const ua = navigator.userAgent;
  const touchMac = /Macintosh/.test(ua) && (navigator.maxTouchPoints || 0) > 1;
  const isIOS = /iPhone|iPad|iPod/.test(ua) || touchMac; // iPadOS reports as Mac
  const isMac = /Macintosh/.test(ua) && !isIOS;
  // Every iOS browser can add to the Home Screen, but only Safari keeps Share
  // on its toolbar. The first outside bug report (2026-09-24, FxiOS) was a
  // reader told to tap a Share button Firefox does not show there.
  if (isIOS && /FxiOS/.test(ua)) return t('install.iosFirefox');
  if (isIOS && /CriOS/.test(ua)) return t('install.iosChrome');
  if (isIOS && /EdgiOS|OPiOS|DuckDuckGo|GSA\//.test(ua)) return t('install.iosOther');
  if (isIOS) return t('install.ios');
  // Off iOS the browser decides whether the app can be installed at all.
  // Chrome, Edge and the other Chromium browsers install from the address bar;
  // Safari adds to the Dock; Firefox and DuckDuckGo on a desktop cannot install
  // web apps, and telling their users to open a File menu that has no such
  // item was reported from DuckDuckGo on a Mac (2026-09-24). DuckDuckGo's
  // desktop browser is WebKit and says "Safari" in its user agent, but it
  // adds "Ddg/", which is what tells it apart.
  const chromium = /Chrome\/|Chromium\/|Edg\//.test(ua);
  const other    = /Firefox\/|Ddg\//.test(ua);
  if (/Android/.test(ua)) return t('install.android');
  if (chromium && !other) return t('install.chromeDesktop');
  if (isMac) return other ? t('install.macOther') : t('install.mac');
  if (other) return t('install.desktopOther');
  return t('install.generic');
}

// The "Work in progress" banner was removed on 2026-09-24. index.html is
// cached apart from app.js, so a stale page may still carry its markup; hide
// it here until the page refreshes.
function hideWipBanner() {
  document.getElementById('wip-banner')?.remove();
}

// The footer's link to the About page (/about/), added 2026-09-24 at the
// maintainer's request. index.html is cached apart from app.js, so a stale
// page lacks the markup; build it here, in front of the copyright line. The
// page it opens is English only, which the Italian label says.
function ensureAboutLink() {
  if (document.querySelector('.app-about')) return;
  const copy = document.querySelector('.app-footer .app-copyright');
  if (!copy) return;
  const p = document.createElement('p');
  p.className = 'app-about';
  const a = document.createElement('a');
  a.href = '/about/';
  a.dataset.i18n = 'footer.about';
  a.textContent = uiLang() === 'it' ? STATIC_IT['footer.about'] : 'About this app';
  p.appendChild(a);
  copy.before(p);
}
// The credits page link beside it (20261025r): the Wikimedia vectorizations
// among the figures carry CC BY-SA licences, whose attribution must reach the
// distributed work, so the app links the credits page from its footer.
function ensureCreditsLink() {
  const p = document.querySelector('.app-about');
  if (!p || p.querySelector('[data-i18n="footer.credits"]')) return;
  p.appendChild(document.createTextNode(' \u00b7 '));
  const a = document.createElement('a');
  a.href = '/about/credits.html';
  a.dataset.i18n = 'footer.credits';
  a.textContent = uiLang() === 'it' ? STATIC_IT['footer.credits'] : 'Image credits';
  p.appendChild(a);
}
// And the repository (20261025s, maintainer: say that it is open source).
function ensureSourceLink() {
  const p = document.querySelector('.app-about');
  if (!p || p.querySelector('[data-i18n="footer.source"]')) return;
  p.appendChild(document.createTextNode(' \u00b7 '));
  const a = document.createElement('a');
  a.href = 'https://github.com/pjgrandinetti/patente-b-for-americans';
  a.rel = 'noopener';
  a.dataset.i18n = 'footer.source';
  a.textContent = uiLang() === 'it' ? STATIC_IT['footer.source'] : 'Open source on GitHub';
  p.appendChild(a);
}

function maybeShowInstallBanner() {
  const banner = document.getElementById('install-banner');
  if (!banner) return;
  if (isAppInstalled() || localStorage.getItem('patente_install_dismissed')) {
    banner.classList.add('hidden');
    return;
  }
  document.getElementById('install-instructions').textContent = installInstructionText();
  banner.classList.remove('hidden');
}

// User-facing level labels. The three words signal the progression: a fully
// English interface, then Italian content (English-labelled), then fully
// Italian. They stay fixed regardless of the current UI language and replace
// the old "L1 / L2 / L3" wording everywhere in the UI.
const LEVEL_LABELS = { 1: 'English', 2: 'Italian', 3: 'Italiano' };

function renderLevelSelector() {
  const container = document.getElementById('level-selector');
  if (!container) return;
  container.innerHTML = '';
  const labels = LEVEL_LABELS;
  // Italian-browser users only need Italiano; hide the English-learner levels.
  // With a single level there's nothing to choose, so render no selector at all.
  const levels = browserPrefersItalian() ? [3] : [1, 2, 3];
  if (levels.length < 2) return;
  for (const lvl of levels) {
    const hint = t('lvl.' + lvl + '.hint');
    const btn  = document.createElement('button');
    btn.className = ['level-btn', currentLevel === lvl ? 'active' : ''].filter(Boolean).join(' ');
    btn.title = hint;
    // The percent cleared is already shown in the dashboard stats above, so the
    // button just names the level.
    btn.innerHTML = `<span class="level-name">${labels[lvl]}</span>`;
    btn.addEventListener('click', () => { setDrillOpen(false); setLevel(lvl); renderDashboard(); });
    container.appendChild(btn);
  }
}

function maybeShowBackupBanner() {
  const banner     = document.getElementById('backup-banner');
  const totalAnswered = Object.values(progress).reduce((s, r) => s + totalSeen(r), 0);
  if (totalAnswered < BACKUP_NUDGE_AFTER) { banner.classList.add('hidden'); return; }

  // When sync is on AND has succeeded at least once, the server already holds an
  // encrypted copy, so a local file backup is largely redundant. The real
  // residual risk is losing the sync code (it lives in this same browser and
  // "can't be recovered" per the sync warning), so nudge about the code instead.
  // Each mode tracks its own dismissal timestamp.
  const synced   = syncEnabled() && !!syncLastAt();
  const ackKey   = synced ? 'patente_code_ack' : 'patente_last_backup';
  const last     = localStorage.getItem(ackKey);
  const stale    = !last || (Date.now() - Number(last)) / 86400000 >= BACKUP_INTERVAL_DAYS;

  document.getElementById('backup-msg-file')?.classList.toggle('hidden', synced);
  document.getElementById('backup-msg-synced')?.classList.toggle('hidden', !synced);
  document.getElementById('btn-export-banner')?.classList.toggle('hidden', synced);
  document.getElementById('btn-code-banner')?.classList.toggle('hidden', !synced);
  banner.classList.toggle('hidden', !stale);
}

