  if (li) return { el: li, block: 'start', pad: true, flash: true };
  const q = currentQuestion();
  if (!q || cardWrongCount(q.id) === 0) return null;
  const box = document.getElementById('card-feedback');
  if (!box || box.classList.contains('hidden')) return null;
