      // maintainer: a comparison to randomly drawn questions means nothing
      // to a casual user).
      (last.range && last.chance != null && edge != null && edge < passMark - 0.5 ? `<p class="weak-note trend-verdict">${escHtml(t(last.range.lo > last.chance ? 'trend.sdChance' : 'trend.sdNote'))}</p>` : '') + `</div>`;
