function playAnswerSound(wasCorrect) {
  if (!soundOn()) return;
  const ctx = answerAudioCtx();
  if (!ctx) return;
  warmAudio();   // first answer of a session also arms the keep-alive
  whenAudioRuns(ctx, () => emitAnswerTone(ctx, wasCorrect));
}

function emitAnswerTone(ctx, wasCorrect) {
  try {
    const now = ctx.currentTime;
    if (wasCorrect) {
      // Rising perfect fourth, A5 then D6: brief and affirmative.
      playTone(ctx, 880,  now,        0.085, 0.10);
      playTone(ctx, 1175, now + 0.09, 0.115, 0.10);
    } else {
      // A falling fifth, E5 then A4. Not a buzz: harsh timbres read as
      // punishment, and the learner is going to hear this one a lot.
      //
      // These were originally 320 and 240 Hz, which was inaudible on a phone at
      // low volume for two compounding reasons. A phone speaker is physically
      // too small to move much air below roughly 500 Hz, so it barely reproduces
      // those notes at all; and human hearing loses sensitivity to low
      // frequencies as level drops (the equal-loudness curves), so what does
      // come out is heard as quieter still, exactly when the volume is low.
      // The high correct tones suffered from neither, which is why one was
      // clearly audible and the other was not. Keeping the sounds distinct
      // therefore cannot mean putting the wrong one in the bass: the contrast
      // has to come from the falling SHAPE and from staying below the correct
      // pair, both of which survive at a pitch the speaker can actually deliver.
      playTone(ctx, 659, now,        0.10, 0.13);
      playTone(ctx, 440, now + 0.10, 0.17, 0.13);
    }
  } catch { /* audio must never break answering */ }
}

// Clearing a whole card with nothing wrong is the real accomplishment, so it
// gets its own sound: a rising major arpeggio (C6 E6 G6 C7) instead of the two
// notes a single right answer earns. Still short, and only a little louder.
//
// It is DELAYED past the answer tone. The last correct answer fires its own
// sound in the same tick as this one, and two overlapping chimes read as a
// glitch rather than a flourish; the gap makes it a phrase, question answered,
// then card cleared. The delay is scheduled on the audio clock, not a timer,
// so it stays exact even if the main thread is busy re-rendering the card.
