const TTS_RATE_KEY = 'patente_tts_rate';
function ttsRate() {
  try {
    const r = parseFloat(localStorage.getItem(TTS_RATE_KEY));
    if (r >= 0.5 && r <= 1.5) return r;
  } catch { }
  return 0.9;
}

